/**
 * Rsx_Timestamp_Format - the engine behind Rsx_Time.format_timestamp(), format_timestamp_short(),
 * format_time_range(), format_date(), format_time() and get_timezone_abbr().
 *
 * The JavaScript twin of Core/Time/Rsx_Timestamp_Format.php: the same algorithm over the same
 * data, line for line, so a browser-rendered label and a server-rendered one are the same
 * string. A change here is a change there. It ships in the VENDOR bundle (Core_Bundle includes
 * it by path), beside the zone abbreviation table it reads, Rsx_Timezone_Abbreviations
 * (rsx_timezone_abbreviations.js, generated by rsx:time:abbreviations).
 *
 * Plain JavaScript with no framework dependency: the zone arithmetic is Intl's, the names are
 * the table's. Application code calls Rsx_Time, never this.
 */
window.Rsx_Timestamp_Format = (function () {
    const PATTERN_LETTERS = 'djmnMFyYDlgGhHisAa';
    const DASH = '–';
    const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July',
        'August', 'September', 'October', 'November', 'December'];
    const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

    const formatters = {};

    function formatter(zone) {
        if (!formatters[zone]) {
            formatters[zone] = new Intl.DateTimeFormat('en-US', {
                timeZone: zone, hourCycle: 'h23',
                year: 'numeric', month: 'numeric', day: 'numeric',
                hour: 'numeric', minute: 'numeric', second: 'numeric',
            });
        }
        return formatters[zone];
    }

    /** The wall-clock numbers of an instant (epoch seconds) in a zone. */
    function wall(epoch, zone) {
        const out = {};
        for (const part of formatter(zone).formatToParts(new Date(epoch * 1000))) {
            if (part.type !== 'literal') out[part.type] = parseInt(part.value, 10);
        }
        if (out.hour === 24) out.hour = 0;
        return out;
    }

    /** The zone's UTC offset at an instant, in seconds. */
    function offset(epoch, zone) {
        const w = wall(epoch, zone);
        return (Date.UTC(w.year, w.month - 1, w.day, w.hour, w.minute, w.second) / 1000) - epoch;
    }

    function pad(value) {
        return (value < 10 ? '0' : '') + value;
    }

    /** The wall-clock fields of an instant in a zone, as strings keyed by pattern letter. */
    function parts(epoch, zone) {
        const w = wall(epoch, zone);
        const weekday = new Date(Date.UTC(w.year, w.month - 1, w.day)).getUTCDay();
        const hour12 = w.hour % 12 === 0 ? 12 : w.hour % 12;

        return {
            d: pad(w.day), j: String(w.day),
            m: pad(w.month), n: String(w.month),
            M: MONTHS[w.month - 1].substr(0, 3), F: MONTHS[w.month - 1],
            y: pad(w.year % 100), Y: String(w.year),
            D: DAYS[weekday].substr(0, 3), l: DAYS[weekday],
            g: String(hour12), G: String(w.hour),
            h: pad(hour12), H: pad(w.hour),
            i: pad(w.minute), s: pad(w.second),
            A: w.hour < 12 ? 'AM' : 'PM', a: w.hour < 12 ? 'am' : 'pm',
        };
    }

    /** A pattern as tokens: ['letter', 'x'] or ['literal', 'text']. Throws on an unsupported letter. */
    function tokenize(pattern, key) {
        const tokens = [];
        for (let index = 0; index < pattern.length; index++) {
            const char = pattern[index];
            if (char === '\\') {
                index++;
                if (index < pattern.length) tokens.push(['literal', pattern[index]]);
                continue;
            }
            if (/^[A-Za-z]$/.test(char)) {
                if (PATTERN_LETTERS.indexOf(char) === -1) {
                    throw new Error(
                        `${key || 'A date pattern'} uses the letter '${char}' in '${pattern}', which RSpade date patterns do not support. `
                        + 'Use only: ' + PATTERN_LETTERS.split('').join(' ') + ' (escape a literal letter with a backslash).'
                    );
                }
                tokens.push(['letter', char]);
                continue;
            }
            tokens.push(['literal', char]);
        }
        return tokens;
    }

    /** The tokens with every meridiem letter, and the literal spaces right before it, removed. */
    function without_meridiem(tokens) {
        const kept = [];
        for (const token of tokens) {
            if (token[0] === 'letter' && (token[1] === 'A' || token[1] === 'a')) {
                while (kept.length && kept[kept.length - 1][0] === 'literal' && kept[kept.length - 1][1] === ' ') kept.pop();
                continue;
            }
            kept.push(token);
        }
        return kept;
    }

    function render(tokens, p) {
        let out = '';
        for (const [kind, value] of tokens) out += kind === 'letter' ? p[value] : value;
        return out;
    }

    /** "UTC", "UTC-3", "UTC+5:30". */
    function offset_name(seconds) {
        if (seconds === 0) return 'UTC';
        const sign = seconds < 0 ? '-' : '+';
        const abs = Math.abs(seconds);
        const hours = Math.floor(abs / 3600);
        const minutes = Math.floor((abs % 3600) / 60);
        return 'UTC' + sign + hours + (minutes > 0 ? ':' + pad(minutes) : '');
    }

    function abbreviation_for_offset(zone, seconds) {
        const table = window.Rsx_Timezone_Abbreviations[zone];
        return (table && table[seconds] !== undefined) ? table[seconds] : offset_name(seconds);
    }

    function zone_abbreviation(epoch, zone) {
        return abbreviation_for_offset(zone, offset(epoch, zone));
    }

    /** ' <ABBR>' when zone differs from viewer_zone at the instant (offset or name), else ''. */
    function suffix(epoch, zone, viewer_zone) {
        if (zone === viewer_zone) return '';
        const own = offset(epoch, zone);
        const abbreviation = abbreviation_for_offset(zone, own);
        const viewer = offset(epoch, viewer_zone);
        if (own === viewer && abbreviation === abbreviation_for_offset(viewer_zone, viewer)) return '';
        return ' ' + abbreviation;
    }

    function long_part(epoch, zone, patterns) {
        const p = parts(epoch, zone);
        return render(tokenize(patterns.date), p) + ' ' + render(tokenize(patterns.time), p);
    }

    function short_date_pattern(p, zone, now_epoch) {
        return p.Y === parts(now_epoch, zone).Y ? 'm-d' : 'm-d-y';
    }

    function short_clock(p, with_meridiem) {
        return p.g + ':' + p.i + (with_meridiem ? p.a[0] : '');
    }

    function short_part(epoch, zone, now_epoch) {
        const p = parts(epoch, zone);
        return render(tokenize(short_date_pattern(p, zone, now_epoch)), p) + ' ' + short_clock(p, true);
    }

    function timestamp(epoch, zone, viewer_zone, patterns) {
        return long_part(epoch, zone, patterns) + suffix(epoch, zone, viewer_zone);
    }

    function timestamp_short(epoch, zone, viewer_zone, now_epoch) {
        return short_part(epoch, zone, now_epoch) + suffix(epoch, zone, viewer_zone);
    }

    function time_range(start, end, zone, viewer_zone, short, now_epoch, patterns) {
        if (end === null) {
            return short ? timestamp_short(start, zone, viewer_zone, now_epoch) : timestamp(start, zone, viewer_zone, patterns);
        }

        const a = parts(start, zone);
        const b = parts(end, zone);
        const same_day = a.Y === b.Y && a.n === b.n && a.j === b.j;
        let body;

        if (short) {
            if (same_day) {
                const meridiem_shared = a.a === b.a;
                body = render(tokenize(short_date_pattern(a, zone, now_epoch)), a)
                    + ' ' + short_clock(a, !meridiem_shared) + DASH + short_clock(b, true);
            } else {
                body = short_part(start, zone, now_epoch) + ' ' + DASH + ' ' + short_part(end, zone, now_epoch);
            }
        } else if (same_day) {
            const time_tokens = tokenize(patterns.time);
            const start_tokens = a.a === b.a ? without_meridiem(time_tokens) : time_tokens;
            body = render(tokenize(patterns.date), a) + ' '
                + render(start_tokens, a).trim() + ' ' + DASH + ' ' + render(time_tokens, b);
        } else {
            body = long_part(start, zone, patterns) + ' ' + DASH + ' ' + long_part(end, zone, patterns);
        }

        return body + suffix(start, zone, viewer_zone);
    }

    function pattern(epoch, zone, text) {
        return render(tokenize(text), parts(epoch, zone));
    }

    function validate_pattern(text, key) {
        if (typeof text !== 'string' || text === '') {
            throw new Error(`${key} must be a non-empty date pattern (e.g. 'M j, Y').`);
        }
        tokenize(text, key);
    }

    return {
        timestamp, timestamp_short, time_range, pattern,
        zone_abbreviation, abbreviation_for_offset, validate_pattern,
    };
})();
